/**
 * The picture of each gesture in the gesture reference: one stroke per label, generated by record
 * mode when it saves templates.json. Normal use only reads this file; nothing is computed at load.
 */
import data from './examples.json';
import type { Pt } from '../types';

/** Example strokes are stored scaled to fit a box this size, keeping their proportions. */
export const EXAMPLE_BOX = 100;

export interface Example {
  points: Pt[];
  /** Chosen in record mode, rather than picked as the most typical sample. */
  pinned: boolean;
}

export interface ExamplesFile {
  version: 1;
  examples: Record<string, Example>;
}

export function parseExamplesFile(json: unknown): ExamplesFile {
  const f = json as Partial<ExamplesFile> | null;
  if (!f || f.version !== 1 || typeof f.examples !== 'object' || f.examples === null) {
    throw new Error('Not a gesture examples file (version 1)');
  }
  return { version: 1, examples: f.examples };
}

/** Label → example stroke, as shipped in examples.json. */
export const examples = new Map(Object.entries(parseExamplesFile(data).examples));
